local PlowMaker = {}
local PRODUCTS = {
    simple_wood_plow = { name = "Preprost leseni plug", woodCost = 3, ironCost = 1, time = 4, cost = 80, food = 15, happiness = 1, description = "Preprost leseni plug za oranje." },
    iron_tipped_plow = { name = "Železnovršni plug", woodCost = 3, ironCost = 2, time = 6, cost = 220, food = 25, happiness = 1, prestige = 2, description = "Železnovršni plug za trgovce." },
    steel_blade_plow = { name = "Jeklenorezni plug", woodCost = 3, ironCost = 2, steelCost = 1, time = 9, cost = 540, food = 38, happiness = 2, prestige = 6, description = "Jeklenorezni plug za plemiče." },
    silver_trimmed_plow = { name = "Srebrnoobrobljeni plug", woodCost = 3, ironCost = 2, silverCost = 1, steelCost = 1, time = 13, cost = 1300, food = 52, happiness = 3, prestige = 14, description = "Srebrnoobrobljeni plug za visoke plemiče." },
    gold_trimmed_plow = { name = "Zlatookrasni plug", woodCost = 3, ironCost = 2, goldCost = 1, silverCost = 1, steelCost = 1, jewelCost = 1, time = 17, cost = 2900, food = 68, happiness = 5, prestige = 27, description = "Plug z draguljem za visoko plemstvo." },
    royal_grand_plow = { name = "Kraljevski veliki plug", woodCost = 5, ironCost = 3, goldCost = 2, silverCost = 2, steelCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 6200, food = 90, happiness = 12, prestige = 58, description = "Veliki kraljevski plug z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    plow_workshop = { name = "Plužna delavnica", cost = { gold = 260, wood = 160, stone = 120, iron = 6 }, upkeep = 6, qualityBonus = 5 },
    agricultural_loft = { name = "Kmetijska podstrešje", cost = { gold = 950, wood = 320, stone = 240, silver = 6, steel = 4 }, upkeep = 22, qualityBonus = 18 },
    master_plow_atelier = { name = "Mojstrski plužni atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_agriculture_palace = { name = "Kraljevska kmetijska palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
PlowMaker.woodStock = 20; PlowMaker.ironStock = 14; PlowMaker.steelStock = 8; PlowMaker.silverStock = 6; PlowMaker.goldStock = 6; PlowMaker.jewelStock = 4; PlowMaker.pearlStock = 4
PlowMaker.productStock = {}; PlowMaker.buildings = {}; PlowMaker.maker = nil; PlowMaker.activeMaking = {}; PlowMaker.totalProducts = 0; PlowMaker.dayTimer = 0
function PlowMaker.init() PlowMaker.woodStock=20; PlowMaker.ironStock=14; PlowMaker.steelStock=8; PlowMaker.silverStock=6; PlowMaker.goldStock=6; PlowMaker.jewelStock=4; PlowMaker.pearlStock=4; PlowMaker.productStock={}; PlowMaker.buildings={}; PlowMaker.maker=nil; PlowMaker.activeMaking={}; PlowMaker.totalProducts=0; PlowMaker.dayTimer=0; print("[PlowMaker] Royal Plow Maker System initialized (6 products, 4 buildings)") end
function PlowMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; PlowMaker.maker={name=n or ("Plužar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Plužar najet: %s (spretnost: %d)",PlowMaker.maker.name,s),"success") end; return true end
function PlowMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function PlowMaker.build(id) local ok,e=PlowMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(PlowMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function PlowMaker.getQualityBonus() local b=0; for _,bd in ipairs(PlowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function PlowMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and PlowMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and PlowMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and PlowMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.silverCost and PlowMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and PlowMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and PlowMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and PlowMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #PlowMaker.buildings==0 then return false,"Potrebna plužna delavnica" end; if not PlowMaker.maker then return false,"Potreben plužar" end; return true end
function PlowMaker.make(pt,qty) qty=qty or 1; local ok,e=PlowMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then PlowMaker.woodStock=PlowMaker.woodStock-d.woodCost*qty end; if d.ironCost then PlowMaker.ironStock=PlowMaker.ironStock-d.ironCost*qty end; if d.steelCost then PlowMaker.steelStock=PlowMaker.steelStock-d.steelCost*qty end; if d.silverCost then PlowMaker.silverStock=PlowMaker.silverStock-d.silverCost*qty end; if d.goldCost then PlowMaker.goldStock=PlowMaker.goldStock-d.goldCost*qty end; if d.jewelCost then PlowMaker.jewelStock=PlowMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then PlowMaker.pearlStock=PlowMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if PlowMaker.maker then t=math.max(1,t-math.floor(PlowMaker.maker.skill/13)) end; table.insert(PlowMaker.activeMaking,{id="plow_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function PlowMaker.completeMaking(m) local q=1.0+(PlowMaker.getQualityBonus()/100); if PlowMaker.maker then q=q+(PlowMaker.maker.skill/140) end; q=math.min(2.5,q); PlowMaker.productStock[m.productType]=(PlowMaker.productStock[m.productType] or 0)+m.quantity; PlowMaker.totalProducts=PlowMaker.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if PlowMaker.maker then PlowMaker.maker.itemsMade=PlowMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then PlowMaker.maker.skill=math.min(100,PlowMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Plug izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"plow.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function PlowMaker.update(dt) if not _G.state then return end; PlowMaker.dayTimer=PlowMaker.dayTimer+dt; if PlowMaker.dayTimer>=30 then PlowMaker.dayTimer=0; for i=#PlowMaker.activeMaking,1,-1 do local m=PlowMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then PlowMaker.completeMaking(m); table.remove(PlowMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(PlowMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if PlowMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function PlowMaker.getStats() return {woodStock=PlowMaker.woodStock,ironStock=PlowMaker.ironStock,steelStock=PlowMaker.steelStock,silverStock=PlowMaker.silverStock,goldStock=PlowMaker.goldStock,jewelStock=PlowMaker.jewelStock,pearlStock=PlowMaker.pearlStock,productStock=PlowMaker.productStock,numBuildings=#PlowMaker.buildings,hasMaker=PlowMaker.maker~=nil,makerName=PlowMaker.maker and PlowMaker.maker.name or "—",makerSkill=PlowMaker.maker and PlowMaker.maker.skill or 0,activeMaking=#PlowMaker.activeMaking,totalProducts=PlowMaker.totalProducts} end
return PlowMaker
